function validate([values]) {
  if (!Array.isArray(values) || values.length < 3 || values.length > 50) return 'values needs 3 to 50 corners.';
  if (values.some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Each value is a whole number from 1 to 100.';
  return null;
}

