function minScoreTriangulation(values) {
  // Every triangulation of 4+ corners has an "ear": a corner whose two neighbours are joined by a diagonal.
  // Cutting off each possible ear and recursing on the remaining corners tries every triangulation;
  // results are cached by the set of corners left.
  const memo = new Map();
  const cut = corners => {
    if (corners.length === 3) return values[corners[0]] * values[corners[1]] * values[corners[2]];
    const key = corners.join(',');
    if (memo.has(key)) return memo.get(key);
    let best = Infinity;
    for (let e = 0; e < corners.length; e++) {
      const before = corners[(e + corners.length - 1) % corners.length];
      const after = corners[(e + 1) % corners.length];
      const rest = corners.filter((_, idx) => idx !== e);
      best = Math.min(best, values[before] * values[corners[e]] * values[after] + cut(rest));
    }
    memo.set(key, best);
    return best;
  };
  return cut(values.map((_, idx) => idx));
}

