function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? pick(40, 50) : pick(3, 7);
  const top = rand() < 0.5 ? 5 : 100;
  return [Array.from({ length: n }, () => pick(1, top))];
}
